  --green-primary: oklch(51% 0.16 160);
  --green-dark: oklch(31% 0.06 150);
  --green-light: oklch(72% 0.10 160);
  --green-pale: oklch(92% 0.04 155);
  --cream-warm: oklch(85% 0.08 70);
  --cream-light: oklch(94% 0.05 72);
  --brown-coffee: oklch(35% 0.05 60);
  --brown-light: oklch(55% 0.06 65);

  /* Neutrals */
  --neutral-0: oklch(100% 0 0);
  --neutral-50: oklch(98% 0.01 160);
  --neutral-100: oklch(95% 0.02 160);
  --neutral-200: oklch(88% 0.02 160);
  --neutral-300: oklch(78% 0.02 160);
  --neutral-400: oklch(62% 0.02 160);
  --neutral-500: oklch(48% 0.02 160);
  --neutral-600: oklch(40% 0.02 160);
  --neutral-700: oklch(30% 0.02 160);
  --neutral-800: oklch(22% 0.02 160);
  --neutral-900: oklch(15% 0.02 160);

  /* Semantic */
  --text-primary: var(--neutral-900);
  --text-secondary: var(--neutral-600);
  --text-muted: var(--neutral-500);
  --text-inverse: var(--neutral-0);
  --bg-page: var(--neutral-50);
  --bg-surface: var(--neutral-0);
  --bg-subtle: var(--neutral-100);
  --border-default: var(--neutral-200);
  --border-strong: var(--neutral-300);

  /* Spacing scale */
  --space-2xs: 0.25rem;
  --space-xs: 0.5rem;
  --space-sm: 0.75rem;
  --space-md: 1rem;
  --space-lg: 1.5rem;
  --space-xl: 2rem;
  --space-2xl: 3rem;
  --space-3xl: 4rem;
  --space-4xl: 6rem;

  /* Radius */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.06);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.08);
  --shadow-lg: 0 8px 24px oklch(0% 0 0 / 0.10);
  --shadow-xl: 0 16px 48px oklch(0% 0 0 / 0.12);
  --shadow-green: 0 4px 16px oklch(51% 0.16 160 / 0.25);

  /* Typography */
  --font-heading: 'DM Serif Display', Georgia, serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: 'JetBrains Mono', 'SF Mono', monospace;

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --duration-fast: 150ms;
  --duration-base: 250ms;
  --duration-slow: 400ms;

  /* Layout */
  --header-height: 72px;
  --content-max: 1200px;
  --content-narrow: 800px;
}

/* --- Reset --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 100%;
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--bg-page);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img, svg {
  display: block;
  max-width: 100%;
}

a {
  color: var(--green-primary);
  text-decoration: none;
  transition: color var(--duration-fast) var(--ease-out);
}
