.card-img {
  border-radius: var(--radius-lg) var(--radius-lg) 0 0;
  overflow: hidden;
  aspect-ratio: 16 / 10;
  background: var(--bg-subtle);
}

.card-img img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.card-body {
  padding: var(--space-lg);
}

.card-flush .card-img {
  border-radius: var(--radius-lg);
  aspect-ratio: 1 / 1;
}

/* --- Hero --- */
.hero {
  position: relative;
  background: linear-gradient(135deg, var(--green-pale) 0%, var(--cream-light) 50%, var(--green-pale) 100%);
  overflow: hidden;
  min-height: 520px;
  display: flex;
  align-items: center;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background:
    radial-gradient(circle at 20% 50%, oklch(51% 0.16 160 / 0.08) 0%, transparent 50%),
    radial-gradient(circle at 80% 30%, oklch(85% 0.08 70 / 0.12) 0%, transparent 50%);
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 600px;
  padding-block: var(--space-4xl);
}

.hero-content h1 {
  margin-bottom: var(--space-md);
