}

.hero-mug {
  width: 280px;
  height: 320px;
  background: var(--bg-surface);
  border-radius: var(--radius-xl) var(--radius-xl) 40px 40px;
  box-shadow: var(--shadow-xl);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
