  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 1rem;
  border-radius: var(--radius-full);
}

.tier-icon {
  font-size: 2.5rem;
  margin-bottom: var(--space-md);
}

.tier-card h3 {
  margin-bottom: var(--space-xs);
}

.tier-threshold {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: var(--space-lg);
}

.tier-benefits {
  list-style: none;
}

.tier-benefits li {
  padding: var(--space-xs) 0;
  color: var(--text-secondary);
  font-size: 0.9375rem;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.tier-benefits li::before {
  content: '✓';
  color: var(--green-primary);
  font-weight: 700;
  flex-shrink: 0;
}

/* Redemption Tabs */
.redemption-tabs {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
  margin-bottom: var(--space-2xl);
  justify-content: center;
}

.redemption-tab {
  padding: 0.625rem 1.25rem;
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
  background: var(--bg-subtle);
  transition: all var(--duration-fast) var(--ease-out);
  cursor: pointer;
  border: 2px solid transparent;
}

.redemption-tab:hover {
  background: var(--green-pale);
  color: var(--green-dark);
}

.redemption-tab.active {
  background: var(--green-primary);
  color: var(--text-inverse);
  border-color: var(--green-primary);
  box-shadow: var(--shadow-green);
}

.redemption-panels {
  position: relative;
  min-height: 200px;
}

.redemption-panel {
  display: none;
  text-align: center;
  padding: var(--space-2xl);
  background: var(--bg-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  animation: fadeSlideIn var(--duration-base) var(--ease-out);
}

.redemption-panel.active {
  display: block;
}

@keyframes fadeSlideIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.redemption-panel .reward-stars {
  font-size: 2.5rem;
  font-family: var(--font-heading);
  color: var(--green-primary);
  margin-bottom: var(--space-sm);
}

.redemption-panel .reward-description {
  font-size: 1.125rem;
  color: var(--text-primary);
  margin-bottom: var(--space-sm);
}

.redemption-panel .reward-value {
  font-size: 0.9375rem;
  color: var(--text-muted);
}

/* Partnerships */
.partnerships-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-xl);
}

.partnership-card {
  display: flex;
  align-items: center;
  gap: var(--space-lg);
  padding: var(--space-xl);
  background: var(--bg-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}

.partnership-icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius-md);
  background: var(--bg-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  flex-shrink: 0;
}

.partnership-info h4 {
  margin-bottom: var(--space-2xs);
}

.partnership-info p {
  color: var(--text-secondary);
  font-size: 0.9375rem;
}

/* --- Gift Cards Page --- */
.gift-hero {
  background: linear-gradient(135deg, var(--cream-light) 0%, var(--green-pale) 100%);
  text-align: center;
  padding-block: var(--space-4xl);
}

.gift-hero h1 {
  margin-bottom: var(--space-md);
}

.gift-hero p {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 560px;
  margin-inline: auto;
  margin-bottom: var(--space-xl);
}

.gift-hero-actions {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  flex-wrap: wrap;
}

/* Carousels */
.carousel-section {
  padding-block: var(--space-3xl);
}

.carousel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-xl);
}

.carousel-title {
  font-family: var(--font-heading);
  font-size: 1.75rem;
}

.carousel-controls {
  display: flex;
  gap: var(--space-xs);
}

.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1px solid var(--border-default);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  color: var(--text-primary);
  background: var(--bg-surface);
  transition: all var(--duration-fast) var(--ease-out);
}

.carousel-btn:hover {
  border-color: var(--green-primary);
  color: var(--green-primary);
  background: var(--green-pale);
}

.carousel-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}

.carousel-track-container {
  overflow: hidden;
  border-radius: var(--radius-lg);
}

.carousel-track {
  display: flex;
  gap: var(--space-lg);
  transition: transform var(--duration-slow) var(--ease-in-out);
}

.gift-card-item {
  flex: 0 0 calc(25% - 0.75rem);
  min-width: 200px;
  aspect-ratio: 3 / 4;
  background: var(--bg-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  text-align: center;
  padding: var(--space-lg);
  cursor: pointer;
  transition: all var(--duration-base) var(--ease-out);
  border: 2px solid transparent;
}

.gift-card-item:hover {
  border-color: var(--green-primary);
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.gift-card-item .gift-emoji {
  font-size: 3rem;
  margin-bottom: var(--space-md);
}

.gift-card-item .gift-label {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-primary);
}

.gift-card-item .gift-price {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-top: var(--space-xs);
}

/* Category Tabs */
.category-tabs {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
  margin-bottom: var(--space-xl);
}

.category-tab {
  padding: 0.5rem 1.25rem;
  border-radius: var(--radius-full);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg-subtle);
  transition: all var(--duration-fast) var(--ease-out);
  cursor: pointer;
  border: 2px solid transparent;
}

.category-tab:hover {
  background: var(--green-pale);
  color: var(--green-dark);
}

.category-tab.active {
  background: var(--green-primary);
  color: var(--text-inverse);
  border-color: var(--green-primary);
}

.category-carousel {
  display: none;
}

.category-carousel.active {
  display: block;
}

/* Business Gifting */
.biz-gifting {
  background: var(--green-dark);
  color: var(--text-inverse);
  padding-block: var(--space-3xl);
}

.biz-gifting .container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
}

.biz-gifting h2 {
  color: var(--text-inverse);
  margin-bottom: var(--space-md);
}

.biz-gifting p {
  color: oklch(85% 0.02 160);
  font-size: 1.0625rem;
  margin-bottom: var(--space-xl);
}

.biz-gifting .btn-primary {
  background: var(--cream-warm);
  color: var(--green-dark);
  box-shadow: none;
}

.biz-gifting .btn-primary:hover {
  background: oklch(90% 0.08 70);
  color: var(--green-dark);
}

.biz-visual {
  aspect-ratio: 1 / 1;
  background: oklch(40% 0.05 160);
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
}

/* eGift Info */
.egift-info {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-3xl);
  align-items: center;
}

.egift-visual {
  aspect-ratio: 4 / 3;
  background: linear-gradient(135deg, var(--green-pale), var(--cream-light));
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
}

.egift-text h2 {
  margin-bottom: var(--space-md);
}

.egift-text p {
  color: var(--text-secondary);
  font-size: 1.0625rem;
  margin-bottom: var(--space-md);
}

/* FAQ */
.faq-list {
  max-width: 700px;
  margin-inline: auto;
}

.faq-item {
  border-bottom: 1px solid var(--border-default);
}

.faq-question {
  width: 100%;
  text-align: left;
  padding: var(--space-lg) 0;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-md);
}

.faq-question::after {
  content: '+';
  font-size: 1.5rem;
  font-weight: 300;
  color: var(--text-muted);
  transition: transform var(--duration-base) var(--ease-out);
}

.faq-item.open .faq-question::after {
  content: '−';
  color: var(--green-primary);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--duration-slow) var(--ease-out);
}

.faq-item.open .faq-answer {
  max-height: 200px;
}

.faq-answer p {
  padding-bottom: var(--space-lg);
  color: var(--text-secondary);
  line-height: 1.7;
}

/* --- Menu Page --- */
.menu-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: var(--space-2xl);
  align-items: start;
  padding-block: var(--space-2xl);
}

.menu-sidebar {
  position: sticky;
  top: calc(var(--header-height) + var(--space-xl));
}

.menu-sidebar h3 {
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: var(--space-sm);
  margin-top: var(--space-lg);
}

.menu-sidebar h3:first-child {
  margin-top: 0;
}

.menu-sidebar a {
  display: block;
  padding: var(--space-xs) var(--space-sm);
  border-radius: var(--radius-sm);
  font-size: 0.9375rem;
  color: var(--text-secondary);
  transition: all var(--duration-fast) var(--ease-out);
}

.menu-sidebar a:hover,
.menu-sidebar a.active {
  background: var(--green-pale);
  color: var(--green-dark);
}

.menu-category-section {
  margin-bottom: var(--space-3xl);
}

.menu-category-section h2 {
  margin-bottom: var(--space-lg);
  padding-bottom: var(--space-sm);
  border-bottom: 2px solid var(--green-pale);
}

.menu-items-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-lg);
}

.menu-item {
  background: var(--bg-surface);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all var(--duration-base) var(--ease-out);
}

.menu-item:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.menu-item-img {
  aspect-ratio: 1 / 1;
  background: var(--bg-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
}

.menu-item-info {
  padding: var(--space-md);
}

.menu-item-info h4 {
  font-size: 1rem;
  margin-bottom: var(--space-2xs);
}

.menu-item-info p {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* Breadcrumb */
.breadcrumb {
  padding-block: var(--space-md);
  font-size: 0.875rem;
  color: var(--text-muted);
}

.breadcrumb a {
  color: var(--text-muted);
}

.breadcrumb a:hover {
  color: var(--green-primary);
}

.breadcrumb span {
  margin-inline: var(--space-xs);
  color: var(--neutral-300);
}

/* --- Store Locator Page --- */
.store-locator-layout {
  display: grid;
  grid-template-columns: 1fr 420px;
  min-height: calc(100vh - var(--header-height));
}

.store-map {
  background: var(--bg-subtle);
  position: relative;
  min-height: 500px;
}

.store-map-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  color: var(--text-muted);
  gap: var(--space-md);
  background:
    radial-gradient(circle at 30% 40%, oklch(51% 0.16 160 / 0.05) 0%, transparent 50%),
    radial-gradient(circle at 70% 60%, oklch(85% 0.08 70 / 0.05) 0%, transparent 50%);
}

.store-map-pin {
  width: 16px;
  height: 16px;
  background: var(--green-primary);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  position: absolute;
  box-shadow: var(--shadow-green);
}

.store-map-pin:nth-child(1) { top: 30%; left: 40%; }
.store-map-pin:nth-child(2) { top: 50%; left: 55%; }
.store-map-pin:nth-child(3) { top: 35%; left: 65%; }
.store-map-pin:nth-child(4) { top: 60%; left: 35%; }
.store-map-pin:nth-child(5) { top: 45%; left: 25%; }
.store-map-pin:nth-child(6) { top: 70%; left: 50%; }

.store-sidebar {
  padding: var(--space-xl);
  border-left: 1px solid var(--border-default);
  background: var(--bg-surface);
  overflow-y: auto;
  max-height: calc(100vh - var(--header-height));
}

.search-controls {
  margin-bottom: var(--space-xl);
}

.search-input-wrap {
  position: relative;
  margin-bottom: var(--space-md);
}

.search-input-wrap .search-icon {
  position: absolute;
  left: var(--space-md);
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
  font-size: 1.125rem;
  pointer-events: none;
}

.search-input {
  width: 100%;
  padding: 0.75rem 1rem 0.75rem 2.75rem;
  border: 2px solid var(--border-default);
  border-radius: var(--radius-full);
  font-size: 0.9375rem;
  background: var(--bg-page);
  transition: border-color var(--duration-fast) var(--ease-out);
}

.search-input:focus {
  outline: none;
  border-color: var(--green-primary);
}

.search-actions {
  display: flex;
  gap: var(--space-sm);
}

.order-type-toggle {
  display: flex;
  background: var(--bg-subtle);
  border-radius: var(--radius-full);
  padding: 4px;
  flex: 1;
}

.order-type-option {
  flex: 1;
  text-align: center;
  padding: 0.5rem;
  border-radius: var(--radius-full);
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all var(--duration-fast) var(--ease-out);
}

.order-type-option.active {
  background: var(--bg-surface);
  color: var(--text-primary);
  box-shadow: var(--shadow-sm);
}

.filter-btn {
  padding: 0.5rem 1rem;
  border: 1px solid var(--border-default);
  border-radius: var(--radius-full);
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--bg-surface);
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}

.filter-btn:hover {
  border-color: var(--green-primary);
}

.filter-panel {
  display: none;
  padding: var(--space-lg);
  background: var(--bg-page);
  border-radius: var(--radius-lg);
  margin-bottom: var(--space-lg);
}

.filter-panel.open {
  display: block;
}

.filter-options {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

.filter-option {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: 0.9375rem;
  cursor: pointer;
}

.filter-option input[type="checkbox"] {
  accent-color: var(--green-primary);
  width: 18px;
  height: 18px;
}

/* Store Results */
.store-results {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.store-result-card {
  padding: var(--space-lg);
  background: var(--bg-page);
  border-radius: var(--radius-md);
  transition: all var(--duration-fast) var(--ease-out);
}

.store-result-card:hover {
  background: var(--green-pale);
}

.store-result-name {
  font-weight: 600;
  margin-bottom: var(--space-2xs);
}

.store-result-addr {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: var(--space-sm);
}

.store-result-meta {
  display: flex;
  gap: var(--space-md);
  font-size: 0.8125rem;
  color: var(--text-secondary);
  flex-wrap: wrap;
}

.store-result-meta span {
  display: flex;
  align-items: center;
  gap: var(--space-2xs);
}

.store-status {
  display: inline-block;
  padding: 0.125rem 0.5rem;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 600;
}

.store-status.open {
  background: oklch(92% 0.06 160);
  color: var(--green-dark);
}

.store-status.closed {
  background: oklch(92% 0.02 30);
  color: oklch(40% 0.06 30);
}

.suggestions-dropdown {
  display: none;
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--bg-surface);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-lg);
  margin-top: 4px;
  z-index: 10;
  overflow: hidden;
}

.suggestions-dropdown.show {
  display: block;
}

.suggestion-item {
  padding: var(--space-sm) var(--space-md);
  font-size: 0.9375rem;
  cursor: pointer;
  transition: background var(--duration-fast);
}

.suggestion-item:hover {
  background: var(--green-pale);
}

/* --- Footer --- */
.site-footer {
  background: var(--neutral-50);
  border-top: 1px solid var(--border-default);
  padding-block: var(--space-3xl) var(--space-xl);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-xl);
  margin-bottom: var(--space-2xl);
}

.footer-col h4 {
  font-size: 0.9375rem;
  font-family: var(--font-body);
  font-weight: 600;
  margin-bottom: var(--space-md);
  color: var(--text-primary);
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: var(--space-sm);
}

.footer-col a {
  font-size: 0.875rem;
  color: var(--text-secondary);
  transition: color var(--duration-fast);
}

.footer-col a:hover {
  color: var(--green-primary);
}

.footer-bottom {
  padding-top: var(--space-xl);
  border-top: 1px solid var(--border-default);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--space-md);
}

.footer-social {
  display: flex;
  gap: var(--space-md);
}

.footer-social a {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--neutral-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  color: var(--text-secondary);
  transition: all var(--duration-fast);
}

.footer-social a:hover {
  background: var(--green-primary);
  color: var(--text-inverse);
}

.footer-legal {
  font-size: 0.8125rem;
  color: var(--text-muted);
}

/* Footer accordion on mobile */
.footer-col-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.footer-col-header .accordion-icon {
  display: none;
  font-size: 1.25rem;
  line-height: 1;
}

/* --- Cookie Banner --- */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 200;
  background: var(--bg-surface);
  border-top: 1px solid var(--border-default);
  box-shadow: 0 -4px 24px oklch(0% 0 0 / 0.12);
  padding: var(--space-lg) var(--space-xl);
  display: flex;
  align-items: center;
  gap: var(--space-xl);
  flex-wrap: wrap;
}

.cookie-banner.hidden {
  display: none;
}

.cookie-text h3 {
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-2xs);
}

.cookie-text p {
  font-size: 0.875rem;
  color: var(--text-secondary);
  max-width: 600px;
}

.cookie-actions {
  display: flex;
  gap: var(--space-sm);
  margin-left: auto;
}

.cookie-actions .btn {
  font-size: 0.875rem;
}

/* --- Utility --- */
.bg-green-pale { background: var(--green-pale); }
.bg-cream-light { background: var(--cream-light); }
.bg-surface { background: var(--bg-surface); }
.text-center { text-align: center; }
.mt-0 { margin-top: 0; }
.mb-lg { margin-bottom: var(--space-lg); }
.mb-xl { margin-bottom: var(--space-xl); }

/* App Download Banner */
.app-download {
  background: linear-gradient(135deg, var(--green-dark) 0%, oklch(25% 0.05 155) 100%);
  color: var(--text-inverse);
  padding-block: var(--space-3xl);
  text-align: center;
}

.app-download h2 {
  color: var(--text-inverse);
  margin-bottom: var(--space-md);
}

.app-download p {
  color: oklch(85% 0.02 160);
  margin-bottom: var(--space-xl);
}

.app-download .btn {
  background: var(--cream-warm);
  color: var(--green-dark);
}

.app-download .btn:hover {
  background: oklch(90% 0.08 70);
  color: var(--green-dark);
}

/* Terms */
.terms-section {
  max-width: var(--content-narrow);
  margin-inline: auto;
  font-size: 0.8125rem;
  color: var(--text-muted);
  line-height: 1.8;
  padding-block: var(--space-3xl);
}

.terms-section h2 {
  font-size: 1.25rem;
  margin-bottom: var(--space-md);
  color: var(--text-secondary);
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .hero-visual {
    display: none;
  }

  .hero-content {
    max-width: 100%;
    text-align: center;
  }

  .seasonal-highlight,
  .feature-row {
    grid-template-columns: 1fr;
    gap: var(--space-xl);
  }

  .seasonal-visual {
    aspect-ratio: 16 / 9;
  }

  .store-locator-layout {
    grid-template-columns: 1fr;
  }

  .store-map {
    min-height: 300px;
  }

  .store-sidebar {
    max-height: none;
    border-left: none;
    border-top: 1px solid var(--border-default);
  }

  .steps-grid,
  .tiers-grid {
    grid-template-columns: 1fr;
    max-width: 500px;
    margin-inline: auto;
  }

  .partnerships-grid {
    grid-template-columns: 1fr;
  }

  .biz-gifting .container,
  .egift-info {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-sm);
  }

  .menu-sidebar h3 {
    width: 100%;
    margin-top: 0;
  }

  .menu-sidebar a {
    display: inline-block;
    padding: var(--space-xs) var(--space-md);
    background: var(--bg-subtle);
    border-radius: var(--radius-full);
    font-size: 0.8125rem;
  }

  .gift-card-item {
    flex: 0 0 calc(33.333% - 0.75rem);
  }
}

@media (max-width: 768px) {
  :root {
    --header-height: 64px;
  }

  .section {
    padding-block: var(--space-2xl);
  }

  .section-lg {
    padding-block: var(--space-3xl);
  }

  /* Mobile nav */
  .nav-primary {
    position: fixed;
    top: var(--header-height);
    left: 0;
    right: 0;
    bottom: 0;
    background: var(--bg-surface);
    flex-direction: column;
    padding: var(--space-xl);
    gap: var(--space-sm);
    transform: translateX(100%);
    transition: transform var(--duration-slow) var(--ease-in-out);
    z-index: 99;
  }

  .nav-primary.open {
    transform: translateX(0);
  }

  .nav-primary a {
    padding: var(--space-md);
    font-size: 1.125rem;
    border-radius: var(--radius-md);
  }

  .nav-toggle {
    display: flex;
  }

  .nav-actions .nav-sign-in,
  .nav-actions .nav-join {
    font-size: 0.75rem;
    padding: 0.375rem 0.75rem;
  }

  /* Footer accordion */
  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-col {
    border-bottom: 1px solid var(--border-default);
  }

  .footer-col-header {
    cursor: pointer;
    padding-block: var(--space-md);
  }

  .footer-col-header .accordion-icon {
    display: block;
    transition: transform var(--duration-base) var(--ease-out);
  }

  .footer-col.open .footer-col-header .accordion-icon {
    transform: rotate(45deg);
  }

  .footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height var(--duration-slow) var(--ease-out);
  }

  .footer-col.open ul {
    max-height: 500px;
    padding-bottom: var(--space-md);
  }

  .cookie-banner {
    flex-direction: column;
    text-align: center;
    gap: var(--space-md);
  }

  .cookie-actions {
    margin-left: 0;
    justify-content: center;
  }

  .promo-grid {
    grid-template-columns: 1fr;
  }

  .gift-card-item {
    flex: 0 0 calc(50% - 0.5rem);
    min-width: 150px;
  }

  .redemption-tabs {
    gap: var(--space-xs);
  }

  .redemption-tab {
    padding: 0.5rem 0.875rem;
    font-size: 0.8125rem;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .carousel-header {
    flex-direction: column;
    gap: var(--space-md);
    align-items: flex-start;
  }
}

@media (max-width: 480px) {
  .gift-card-item {
    flex: 0 0 calc(50% - 0.5rem);
    min-width: 130px;
  }

  .search-actions {
    flex-direction: column;
  }

  .hero-content h1 {
    font-size: 2rem;
  }

  .category-tabs {
    gap: var(--space-xs);
  }

  .category-tab {
    padding: 0.375rem 0.75rem;
    font-size: 0.75rem;
  }

  .cookie-actions {
    flex-direction: column;
    width: 100%;
  }

  .cookie-actions .btn {
    width: 100%;
  }
}
