.cookie-text h3 {
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-2xs);
}

.cookie-text p {
  font-size: 0.875rem;
  color: var(--text-secondary);
  max-width: 600px;
}

.cookie-actions {
  display: flex;
  gap: var(--space-sm);
  margin-left: auto;
}

