.bg-cream-light { background: var(--cream-light); }
.bg-surface { background: var(--bg-surface); }
.text-center { text-align: center; }
.mt-0 { margin-top: 0; }
.mb-lg { margin-bottom: var(--space-lg); }
.mb-xl { margin-bottom: var(--space-xl); }

